frappe.ready(function () {
	// --------------------------------------------------
	// Sets the declaration consent as mandatory based on the candidate's age (under 18).
	// --------------------------------------------------
	function toggle_declaration_section() {
		try {
			const dob_val = frappe.web_form.get_value('candidate_dob');
			let is_mandatory = false;
			let age = null;

			if (dob_val) {
				const dob = new Date(dob_val);
				const today = new Date();
				age = today.getFullYear() - dob.getFullYear();
				const m = today.getMonth() - dob.getMonth();

				if (m < 0 || (m === 0 && today.getDate() < dob.getDate())) {
					age--;
				}

				if (age < 18) {
					is_mandatory = true;
				}
			}

			if (typeof frappe.web_form.set_df_property === 'function') {
				frappe.web_form.set_df_property('declaration_consent', 'reqd', is_mandatory ? 1 : 0);
			} else if (frappe.web_form.fields_dict && frappe.web_form.fields_dict['declaration_consent']) {
				frappe.web_form.fields_dict['declaration_consent'].df.reqd = is_mandatory ? 1 : 0;
				frappe.web_form.fields_dict['declaration_consent'].refresh();
			}

		} catch (e) {
			// Error handling silently in production or log to system console if available
		}
	}

	frappe.web_form.on('candidate_dob', function () {
		toggle_declaration_section();
	});

	// Run on load
	// Run on load
	toggle_declaration_section();

	// Inject Custom Header, Footer, and CSS
	$('head').append('<link href="https://fonts.googleapis.com/css2?family=Merriweather:wght@300;400;700&display=swap" rel="stylesheet">');
	$('head').append('<link rel="stylesheet" href="/fle/css/login.css">');

	const header_html = `
	<header class="sticky-header">
		<div class="header-top">
			<div class="logo-container">
				<img src="/files/nlsiu-logo.jpg" alt="Logo" class="logo-img">
			</div>
			<div class="brand-text">
				<h5 class="university-name">National Law School of India University, Bengaluru</h5>
				<h1 class="department-name">Foundations for a Legal Education Certificate Course</h1>
			</div>
			<div class="header-spacer"></div>
		</div>
		<nav class="navbar-navy">
			<a href="#" class="nav-item">OVERVIEW</a>
			<a href="#" class="nav-item">COURSES</a>
			<a href="#" class="nav-item">FACULTY</a>
			<a href="#" class="nav-item">FEE</a>
			<a href="#" class="nav-item">FAQs</a>
			<a href="#" class="nav-item">Contact Us</a>
		</nav>
	</header>
	`;

	const footer_html = `
	<footer class="sticky-footer">
		© 2026 National Law School of India University. All Rights Reserved.
	</footer>
	`;

	$('body').prepend(header_html);
	$('body').append(footer_html);

	// Add specific fixes for sticky positioning in Web Forms
	$('html, body').css({
		'overflow-x': 'hidden',
		// Frappe often sets overflow-y to hidden or auto on body which breaks sticky headers
		'height': '100%',
		'position': 'relative'
	});

	// Ensure the middle content expands to push footer down
	$('body').css({
		'display': 'flex',
		'flex-direction': 'column',
		'min-height': '100vh',
		'margin': '0'
	});

	// Frappe web forms usually have .page-container or similar as main wrapper
	$('.web-form-page, .page-container').css('flex', '1 0 auto');

	// Fix z-index and top positioning specifically for frappe DOM
	$('.sticky-header').css({
		'position': 'fixed',
		'top': '0',
		'left': '0',
		'z-index': '1020', // Higher than Frappe's default nav
		'width': '100%'
	});

	$('body').css('padding-top', $('.sticky-header').outerHeight() + 'px');

	// Ensure the footer is sticky at the very bottom
	$('.sticky-footer').css({
		'margin-top': 'auto', // Pushes footer to bottom in flex
		'width': '100%'
	});
});
